mapper.select:
SELECT id, username, password_hash, display_name, created_at, updated_at
FROM marketplace_users
WHERE username = #{username}

SELECT id, username, password_hash, display_name, created_at, updated_at
FROM marketplace_users
WHERE id = #{id}

SELECT token_hash, user_id, expires_at, revoked_at, last_seen_at, created_at
FROM marketplace_sessions
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE marketplace_sessions
SET revoked_at = #{revokedAt}
WHERE token_hash = #{tokenHash} AND revoked_at IS NULL

UPDATE marketplace_sessions
SET last_seen_at = #{lastSeenAt}
WHERE token_hash = #{tokenHash}

mapper.select:
SELECT id, name, slug, sort_order, created_at
FROM marketplace_categories
WHERE id = #{id}

SELECT FROM marketplace_items i JOIN marketplace_users seller ON seller.id = i.seller_id JOIN marketplace_categories category ON category.id = i.category_id WHERE 1 = 1
AND i.seller_id = #{sellerId}
AND i.status = 'LISTED'
AND i.category_id = #{categoryId}
AND (LOWER(i.title) LIKE #{q} OR LOWER(i.description) LIKE #{q})
ORDER BY i.created_at DESC, i.id DESC

SELECT m.id, m.conversation_id, m.sender_id, sender.username AS sender_username,
       sender.display_name AS sender_display_name, m.body, m.created_at
FROM marketplace_messages m
JOIN marketplace_users sender ON sender.id = m.sender_id
WHERE m.conversation_id = #{conversationId}

    AND m.id > #{afterId}

ORDER BY m.id
LIMIT #{limit}
